-- =============================================================================
-- 488 — LE CAHIER D'EXERCICES DE 4E (partie 7)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 488 --niveau 4e --fichiers maths.n2,maths.n3,musique.jumelles --suffixe 7 > supabase/contenu/488_exercices_4e_7.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths.n2                36 exercices · 12 chapitres
--   maths.n3                36 exercices · 12 chapitres
--   musique.jumelles         9 exercices · 3 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les crêpes de la kermesse","competence":"calculer","situation":"Inès prépare la pâte à crêpes pour la kermesse du collège. Sa recette est écrite pour plusieurs nombres de personnes, mais une case du tableau est restée vide.","documents":[{"id":"recette","type":"tableau","titre":"La recette d’Inès","source":"Quantités imaginées pour l’exercice","colonnes":["Nombre de personnes","4","8","12","6"],"lignes":[["Farine (g)",200,400,600,"?"],["Lait (cL)",50,100,150,75]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la quantité de **lait** pour **12 personnes**.","aide":"Cherche la ligne du lait, puis la colonne « 12 ».","type":"zone","document":"recette","multiple":false},{"enonce":"Complète pour trouver la farine d’**une** personne.","aide":"Divise la farine d’une colonne par le nombre de personnes de cette colonne.","type":"trous","segments":["Pour 1 personne, il faut ",0," g de farine."],"banque":["50","25","800","100"]},{"enonce":"Combien de grammes de farine faut-il pour **6 personnes** (la case « ? ») ?","aide":"Multiplie le nombre de personnes par la farine d’une personne.","type":"nombre","unite":"g"},{"enonce":"Inès n’a que **750 g** de farine. Pour combien de personnes sa recette suffit-elle ?","aide":"Cette fois, c’est la farine qu’on connaît : combien de fois 50 g y a-t-il dans 750 g ?","type":"nombre","unite":"personnes"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c3"]},"explication":"Pour 12 personnes, la recette demande **150 cL de lait** : c’est la case de la ligne « Lait » sous la colonne 12."},{"cle":{"type":"trous","trous":[["50"]]},"affichage":"50","explication":"200 ÷ 4 = **50** : une personne mange 50 g de farine. C’est le coefficient de proportionnalité entre les deux lignes."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 g","explication":"6 × 50 = **300 g**. On retrouve aussi 300 = 200 + 100, la farine de 4 personnes plus celle de 2."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 personnes","explication":"750 ÷ 50 = **15 personnes**. Quand on connaît la farine, on divise par le coefficient."}]$ex$::jsonb),
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux formules pour louer un vélo","competence":"lire-graphique","situation":"À la plage, Malik hésite entre deux formules de location de vélo. Le loueur a tracé le prix à payer selon la durée de location.","documents":[{"id":"tarifs","type":"graphique","forme":"courbe","titre":"Prix de la location selon la durée","source":"Tarifs imaginés pour l’exercice","categories":["0 h","1 h","2 h","3 h","4 h","5 h","6 h"],"series":[{"nom":"Formule Libre","valeurs":[0,7,14,21,28,35,42],"teinte":"bleu"},{"nom":"Formule Dossier","valeurs":[8,13,18,23,28,33,38],"teinte":"corail"}],"axeY":{"titre":"Prix","unite":"€","min":0,"max":42,"pas":7},"axeX":{"titre":"Durée de location"}}],"questions":[{"enonce":"Quelle formule est **proportionnelle** à la durée de location ?","aide":"Regarde ce que coûte chaque formule quand la durée est de 0 h.","type":"choix","options":[{"id":"a","texte":"La formule Libre"},{"id":"b","texte":"La formule Dossier"},{"id":"c","texte":"Les deux formules"},{"id":"d","texte":"Aucune des deux"}],"multiple":false},{"enonce":"Touche la durée pour laquelle les deux formules coûtent **le même prix**.","aide":"Cherche l’endroit où les deux courbes se croisent.","type":"zone","document":"tarifs","multiple":false},{"enonce":"La formule Libre est proportionnelle. Combien coûteraient **9 heures** de location ?","aide":"Cherche le prix d’une heure, puis multiplie par 9.","type":"nombre","unite":"€"},{"enonce":"Pour **3 heures**, de combien d’euros la formule la moins chère est-elle moins chère que l’autre ?","aide":"Lis le prix de chaque formule à 3 h, puis fais la différence.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"La formule **Libre** : 0 h coûte 0 €, et le prix double quand la durée double. La formule Dossier démarre à 8 € : il y a une part fixe, donc pas de proportionnalité."},{"cle":{"type":"zone","ids":["k4"]},"explication":"À **4 h**, les deux formules coûtent 28 €. Avant, la formule Libre est la moins chère ; après, c’est l’autre."},{"cle":{"type":"nombre","valeur":63,"tolerance":0},"affichage":"63 €","explication":"Une heure coûte 7 €, donc 9 h coûtent 9 × 7 = **63 €**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 €","explication":"À 3 h : 21 € pour Libre et 23 € pour Dossier. La différence est de 23 − 21 = **2 €**."}]$ex$::jsonb),
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La sortie accrobranche de Zoé","competence":"raisonner","situation":"Zoé organise une sortie accrobranche pour sa classe. Elle compare les tarifs de deux parcs et lit l’avis d’Hugo dans la discussion du groupe.","documents":[{"id":"prix","type":"tableau","titre":"Prix de groupe selon le nombre d’enfants","source":"Tarifs imaginés pour l’exercice","colonnes":["Nombre d’enfants","2","4","6","8","10"],"lignes":[["Parc des Cimes (€)",30,60,90,120,150],["Parc Tarzan (€)",50,80,110,140,170]],"enteteLignes":true},{"id":"chat","type":"dialogue","modele":"sms","titre":"La discussion du groupe","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Zoé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Au parc Tarzan, 6 enfants coûtent 110 €. Pour 12 enfants, je double : 220 €."},{"qui":"Zoé","texte":"Hmm, je ne suis pas sûre que ça marche…"}]}],"questions":[{"enonce":"Au **parc des Cimes**, combien coûte la sortie **par enfant** ?","aide":"Divise le prix d’une colonne par le nombre d’enfants de cette colonne.","type":"nombre","unite":"€"},{"enonce":"Combien paie-t-on aux Cimes pour **13 enfants** ?","aide":"Le parc des Cimes est proportionnel : utilise le prix par enfant.","type":"nombre","unite":"€"},{"enonce":"Range chaque situation : proportionnelle ou non ?","aide":"Dans une proportionnalité, quand l’une des grandeurs est nulle, l’autre l’est aussi, et quand l’une double, l’autre double.","type":"categories","categories":[{"id":"c0","texte":"Proportionnelle"},{"id":"c1","texte":"Pas proportionnelle"}],"items":[{"id":"i0","texte":"Âge de Zoé selon l’âge de son petit frère"},{"id":"i1","texte":"Prix chez Tarzan selon le nombre d’enfants"},{"id":"i2","texte":"Prix aux Cimes selon le nombre d’enfants"},{"id":"i3","texte":"Aire d’un carré selon son côté"},{"id":"i4","texte":"Périmètre d’un carré selon son côté"}]},{"enonce":"Pourquoi le calcul d’Hugo (220 €) est-il faux ?","aide":"Compare 110 € pour 6 enfants avec ce que coûtent 12 enfants si le prix doublait : retrouve-t-on le tableau ?","type":"choix","options":[{"id":"a","texte":"Il aurait dû tripler le prix puis le diviser par deux"},{"id":"b","texte":"Le prix chez Tarzan n’est pas proportionnel au nombre d’enfants"},{"id":"c","texte":"Il a oublié une remise de groupe pour 12 enfants"},{"id":"d","texte":"Il a mal recopié le prix de 6 enfants du tableau"}],"multiple":false},{"enonce":"Combien coûtent vraiment **12 enfants** au parc Tarzan ?","aide":"Pars de 10 enfants (170 €) et ajoute le prix de 2 enfants de plus.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 €","explication":"30 ÷ 2 = 15, et 60 ÷ 4 = 15 : le quotient est le même partout, c’est **15 € par enfant**."},{"cle":{"type":"nombre","valeur":195,"tolerance":0},"affichage":"195 €","explication":"13 × 15 = **195 €**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Seuls le **prix aux Cimes** et le **périmètre du carré** (P = 4 × c) sont proportionnels. L’aire varie comme c², Tarzan a une part fixe, et l’écart d’âge entre deux personnes ne change pas."},{"cle":{"type":"choix","ids":["b"]},"explication":"Chez Tarzan, une part fixe de 20 € s’ajoute au prix des enfants : **doubler le nombre d’enfants ne double pas le prix**. Le doublement ne marche que dans une situation proportionnelle."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 €","explication":"De 10 à 12 enfants, on ajoute 2 enfants, soit 30 € : 170 + 30 = **200 €**. Chaque enfant coûte 15 € et il y a 20 € fixes : 20 + 12 × 15 = 200."}]$ex$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les soldes du magasin de sport","competence":"calculer","situation":"Inès profite des soldes : le magasin affiche −20 % sur tout le rayon. Elle veut savoir ce qu’elle économise sur chaque article.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"SOLDES −20 %","sousTitre":"Sur tout le rayon, remise déduite en caisse","emoji":"🏷️","teinte":"corail","source":"Prix imaginés pour l’exercice","lignes":[{"texte":"Sweat à capuche","valeur":"45 €","id":"z1"},{"texte":"Casquette","valeur":"12 €","id":"z2"},{"texte":"Sac à dos","valeur":"30 €","id":"z3"},{"texte":"Survêtement","valeur":"60 €","id":"z4"}]}],"questions":[{"enonce":"Quelle remise Inès obtient-elle sur le **sweat à capuche** ?","aide":"Prendre 20 %, c’est multiplier par 20 ÷ 100, soit 0,2.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix soldé du **sac à dos** ?","aide":"Enlève la remise au prix de départ, ou multiplie directement par un seul coefficient.","type":"nombre","unite":"€"},{"enonce":"Par quel coefficient multiplie-t-on un prix de départ pour obtenir le prix soldé ?","aide":"On garde 100 % − 20 % du prix.","type":"choix","options":[{"id":"a","texte":"0,2"},{"id":"b","texte":"0,8"},{"id":"c","texte":"1,2"},{"id":"d","texte":"20"}],"multiple":false},{"enonce":"Touche l’article dont la **remise en euros** est la plus grande.","aide":"La remise est toujours 20 % du prix : le prix le plus haut donne la plus grosse remise.","type":"zone","document":"affiche","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 €","explication":"20 % de 45 € = 45 × 0,2 = **9 €**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 €","explication":"La remise est de 30 × 0,2 = 6 €, donc le prix soldé est 30 − 6 = **24 €**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Une baisse de 20 % se traduit par un coefficient de 1 − 0,2 = **0,8**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Le **survêtement** (60 €) a la plus grande remise : 60 × 0,2 = 12 €, contre 9 €, 6 € et 2,40 € pour les autres."}]$ex$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le prix de la place de cinéma","competence":"modeliser","situation":"Le cinéma de quartier a changé plusieurs fois le prix de sa place. Marwan veut comprendre ce que ces évolutions donnent au total.","documents":[{"id":"prix","type":"graphique","forme":"barres","titre":"Prix d’une place au tarif plein","source":"Prix imaginés pour l’exercice","categories":["2021","2022","2023"],"series":[{"nom":"Prix de la place","valeurs":[8,9,9.9],"teinte":"violet"}],"axeY":{"titre":"Prix","unite":"€","min":0,"max":12,"pas":2},"valeurs":true}],"questions":[{"enonce":"De 2021 à 2022, le prix passe de 8 € à 9 €. Quel est le **taux d’évolution**, en % ?","aide":"Taux = (valeur finale − valeur initiale) ÷ valeur initiale × 100.","type":"nombre","unite":"%"},{"enonce":"Touche l’année où le prix a **augmenté de 10 %** par rapport à l’année précédente.","aide":"Calcule le taux d’évolution pour chaque année, ou multiplie 9 € par 1,1.","type":"zone","document":"prix","multiple":false},{"enonce":"En 2024, le cinéma **baisse de 10 %** le prix de 2023. Quel est le prix de la place en 2024 ?","aide":"Baisser de 10 %, c’est multiplier par 0,9.","type":"nombre","unite":"€"},{"enonce":"Entre 2022 et 2024, le prix a été multiplié par 1,1 puis par 0,9. Que dire de l’évolution totale ?","aide":"On multiplie les coefficients : calcule 1,1 × 0,9.","type":"choix","options":[{"id":"a","texte":"Une baisse de 1 % en tout"},{"id":"b","texte":"Une baisse de 20 % en tout"},{"id":"c","texte":"Un retour exact au prix de 2022"},{"id":"d","texte":"Une hausse de 1 % en tout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":12.5,"tolerance":0},"affichage":"12,5 %","explication":"(9 − 8) ÷ 8 × 100 = **12,5 %** : l’augmentation est ramenée au prix de départ, 8 €."},{"cle":{"type":"zone","ids":["k2"]},"explication":"**2023** : 9 × 1,1 = 9,90 €. De 2021 à 2022, la hausse est de 12,5 %, pas de 10 %."},{"cle":{"type":"nombre","valeur":8.91,"tolerance":0},"affichage":"8,91 €","explication":"9,90 × 0,9 = **8,91 €**."},{"cle":{"type":"choix","ids":["a"]},"explication":"1,1 × 0,9 = 0,99, donc **une baisse de 1 %** : une hausse puis une baisse du même taux ne ramènent jamais au prix de départ."}]$ex$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quelle trottinette est la moins chère ?","competence":"raisonner","situation":"Samir veut acheter une trottinette électrique à 120 €. Deux sites l’affichent avec des remises différentes, et il pense que ça revient au même prix.","documents":[{"id":"siteA","type":"fiche","modele":"affiche","entete":"Rapido-Trott","sousTitre":"Trottinette électrique","emoji":"🛴","teinte":"bleu","source":"Offres imaginées pour l’exercice","lignes":[{"texte":"Prix catalogue","valeur":"120 €"},{"texte":"Remise de lancement","valeur":"−20 %"},{"texte":"Code promo sur le prix déjà remisé","valeur":"−10 %"}]},{"id":"siteB","type":"fiche","modele":"affiche","entete":"Trott&Co","sousTitre":"La même trottinette","emoji":"🛴","teinte":"turquoise","source":"Offres imaginées pour l’exercice","lignes":[{"texte":"Prix catalogue","valeur":"120 €"},{"texte":"Remise immédiate","valeur":"−30 %"}]},{"id":"chat","type":"dialogue","modele":"sms","participants":[{"nom":"Samir","emoji":"👦","cote":"gauche"},{"nom":"Lina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Samir","texte":"Chez Rapido-Trott c’est −20 % puis −10 % : 20 + 10 = 30 %. C’est le même prix que chez Trott&Co !"},{"qui":"Lina","texte":"Tu es sûr ? Calcule les deux prix avant de commander."}]}],"questions":[{"enonce":"Chez Rapido-Trott, quel est le prix après la **première** remise (−20 %) ?","aide":"Multiplie 120 € par 0,8.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix **final** chez Rapido-Trott, après le code promo de −10 % ?","aide":"Le code promo s’applique sur le prix déjà remisé (96 €), pas sur 120 €.","type":"nombre","unite":"€"},{"enonce":"Quel est le prix chez Trott&Co, avec −30 % sur 120 € ?","aide":"Un seul coefficient : 1 − 0,3.","type":"nombre","unite":"€"},{"enonce":"Pourquoi Samir a-t-il tort de penser que −20 % puis −10 % reviennent à −30 % ?","aide":"Sur quel prix chaque pourcentage est-il calculé ?","type":"choix","options":[{"id":"a","texte":"Le code promo est toujours supérieur à la remise de lancement"},{"id":"b","texte":"Il faut soustraire les deux pourcentages, pas les additionner"},{"id":"c","texte":"La seconde remise porte sur le prix déjà réduit, pas sur le prix de départ"},{"id":"d","texte":"Les pourcentages ne s’appliquent qu’une fois"}],"multiple":false},{"enonce":"Quelle **baisse unique**, en %, serait équivalente à −20 % puis −10 % ?","aide":"Multiplie les deux coefficients, puis cherche de combien la baisse est équivalente.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":96,"tolerance":0},"affichage":"96 €","explication":"120 × 0,8 = **96 €**."},{"cle":{"type":"nombre","valeur":86.4,"tolerance":0},"affichage":"86,4 €","explication":"96 × 0,9 = **86,40 €**."},{"cle":{"type":"nombre","valeur":84,"tolerance":0},"affichage":"84 €","explication":"120 × 0,7 = **84 €**."},{"cle":{"type":"choix","ids":["c"]},"explication":"**On ne calcule pas les deux pourcentages sur la même quantité** : −10 % de 96 € enlève moins que −10 % de 120 €. Les évolutions successives se multiplient (coefficients), elles ne s’additionnent pas."},{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28 %","explication":"0,8 × 0,9 = 0,72, soit un coefficient de 1 − 0,28 : une baisse de **28 %**, et pas de 30 %."}]$ex$::jsonb),
  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La randonnée de Sacha","competence":"lire-graphique","situation":"Sacha fait une randonnée en montagne. Son altimètre a relevé son altitude toutes les heures depuis le départ, et le graphique montre l’allure de sa journée.","documents":[{"id":"alti","type":"graphique","forme":"courbe","titre":"Altitude de Sacha au cours de la randonnée","source":"Relevés imaginés pour l’exercice","categories":["0 h","1 h","2 h","3 h","4 h","5 h","6 h"],"series":[{"nom":"Altitude","valeurs":[300,600,900,900,1200,900,600],"teinte":"brun"}],"axeY":{"titre":"Altitude","unite":"m","min":0,"max":1500,"pas":300},"axeX":{"titre":"Temps depuis le départ"}}],"questions":[{"enonce":"Quelle grandeur est la **variable**, placée en abscisse ?","aide":"Regarde ce qui est écrit sous l’axe horizontal.","type":"choix","options":[{"id":"a","texte":"L’altitude"},{"id":"b","texte":"La longueur du sentier"},{"id":"c","texte":"Le temps écoulé"},{"id":"d","texte":"La vitesse de Sacha"}],"multiple":false},{"enonce":"Quelle est l’altitude de Sacha au bout de **4 heures** ?","aide":"Pars de 4 h sur l’axe horizontal, monte jusqu’à la courbe, puis lis à gauche.","type":"nombre","unite":"m"},{"enonce":"Sacha fait une pause. Touche les **deux repères de temps** entre lesquels son altitude ne change pas.","aide":"Cherche le morceau horizontal de la courbe, appelé un palier.","type":"zone","document":"alti","multiple":true},{"enonce":"Combien de mètres Sacha a-t-il **perdus en altitude** entre 4 h et 6 h ?","aide":"Lis l’altitude à 4 h et à 6 h, puis fais la différence.","type":"nombre","unite":"m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"On place **le temps** en abscisse : c’est la grandeur qu’on choisit. L’altitude en dépend et se lit en ordonnée."},{"cle":{"type":"nombre","valeur":1200,"tolerance":0},"affichage":"1200 m","explication":"À 4 h, la courbe est à **1 200 m**."},{"cle":{"type":"zone","ids":["k2","k3"]},"explication":"Entre **2 h et 3 h**, la courbe est horizontale : l’altitude reste à 900 m, c’est un palier."},{"cle":{"type":"nombre","valeur":600,"tolerance":0},"affichage":"600 m","explication":"1 200 − 600 = **600 m** : sur cette partie, la courbe est décroissante."}]$ex$::jsonb),
  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux formules à la salle d’escalade","competence":"modeliser","situation":"Lou veut s’inscrire à la salle d’escalade « Les Grimpeurs », qui propose deux formules. Il cherche laquelle choisir selon le nombre de séances.","documents":[{"id":"tarifs","type":"fiche","modele":"affiche","entete":"Les Grimpeurs","sousTitre":"Nos deux formules","emoji":"🧗","teinte":"ambre","source":"Tarifs imaginés pour l’exercice","lignes":[{"texte":"Formule A : P = 5 × n","valeur":"5 € la séance"},{"texte":"Formule B : P = 20 + 3 × n","valeur":"20 € d’inscription + 3 € la séance"}],"pied":"P est le prix en euros, n le nombre de séances."},{"id":"table","type":"tableau","titre":"Prix selon le nombre de séances","colonnes":["Séances (n)","0","2","4","6","8"],"lignes":[["Formule A (€)",0,10,20,30,40],["Formule B (€)",20,26,32,38,44]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque formule à sa description.","aide":"Regarde si le prix part de 0 € quand on ne fait aucune séance.","type":"association","gauche":[{"id":"g0","texte":"Formule A"},{"id":"g1","texte":"Formule B"}],"droite":[{"id":"d0","texte":"Une part fixe s’ajoute au prix des séances"},{"id":"d1","texte":"Le prix est proportionnel au nombre de séances"}]},{"enonce":"Touche la case du tableau qui montre que la formule **B** n’est **pas** proportionnelle.","aide":"Dans une proportionnalité, 0 séance doit coûter 0 €.","type":"zone","document":"table","multiple":false},{"enonce":"Avec la formule B, combien Lou paie-t-il pour **12 séances** ?","aide":"Applique la formule : P = 20 + 3 × n avec n = 12.","type":"nombre","unite":"€"},{"enonce":"Pour combien de séances les deux formules coûtent-elles **exactement le même prix** ?","aide":"À 8 séances, A coûte 40 € et B 44 € : de combien l’écart diminue-t-il à chaque séance supplémentaire ?","type":"nombre","unite":"séances"}]}$ex$::jsonb,
