  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Remplir le bassin du centre aquatique","competence":"modeliser","situation":"Au centre aquatique, on remplit un bassin de 60 m³ avec la pompe A. Le technicien a tracé le volume d’eau en fonction du temps, puis il compare avec une pompe B plus puissante.","documents":[{"id":"volume","type":"graphique","forme":"courbe","titre":"Volume d’eau dans le bassin (pompe A)","source":"Relevés imaginés pour l’exercice","categories":["0 min","10 min","20 min","30 min","40 min","50 min","60 min"],"series":[{"nom":"Volume d’eau","valeurs":[0,30,60,60,60,40,20],"teinte":"bleu"}],"axeY":{"titre":"Volume","unite":"m³","min":0,"max":70,"pas":10},"axeX":{"titre":"Temps"}},{"id":"pompeB","type":"tableau","titre":"La pompe B, essayée seule","colonnes":["Temps (min)","5","10","15","20"],"lignes":[["Volume (m³)",20,40,60,80]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le volume d’eau dans le bassin au bout de **20 minutes** ?","aide":"Lis l’ordonnée du point qui correspond à 20 min.","type":"nombre","unite":"m³"},{"enonce":"Touche **tous** les temps où le bassin contient exactement 60 m³.","aide":"Cherche le palier horizontal de la courbe.","type":"zone","document":"volume","multiple":true},{"enonce":"Pendant les 20 premières minutes, de combien de m³ le volume augmente-t-il **par minute** ?","aide":"Le volume passe de 0 à 30 m³ en 10 minutes.","type":"nombre","unite":"m³/min"},{"enonce":"Le volume du bassin est-il proportionnel au temps sur l’ensemble des 60 minutes ?","aide":"Dépendre n’est pas la même chose qu’être proportionnel : quelle forme doit avoir la courbe ?","type":"choix","options":[{"id":"a","texte":"Oui : à chaque temps correspond un seul volume"},{"id":"b","texte":"Oui : la courbe part de 0 m³ au début du remplissage"},{"id":"c","texte":"Non : le volume ne dépend absolument pas du temps"},{"id":"d","texte":"Non : la courbe n’est pas une droite passant par l’origine"}],"multiple":false},{"enonce":"Avec la pompe B seule, de combien de minutes gagne-t-on pour atteindre 60 m³ par rapport à la pompe A ?","aide":"Lis dans le tableau le temps que met la pompe B pour atteindre 60 m³, puis compare avec la pompe A.","type":"nombre","unite":"min"}]}$ex$::jsonb,
