  ('f91e9054-fdd3-5d3e-8910-de90cc5862b9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dessiner le pavé en perspective","competence":"geometrie","situation":"Karim a dessiné un pavé droit en perspective cavalière pour son cours de technologie. La face avant ABFE est en vraie grandeur et les arêtes cachées sont en pointillés.","documents":[{"id":"pave","type":"figure","titre":"Le pavé en perspective cavalière","source":"Dessin réalisé pour l’exercice : la face avant est en vraie grandeur","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":7},"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":6,"y":1,"position":"se"},{"id":"F","x":6,"y":4,"position":"se"},{"id":"E","x":1,"y":4,"position":"no"},{"id":"D","x":3,"y":2.5,"position":"se"},{"id":"C","x":8,"y":2.5,"position":"e"},{"id":"G","x":8,"y":5.5,"position":"ne"},{"id":"H","x":3,"y":5.5,"position":"n"}],"segments":[{"id":"z1","de":"A","a":"B","longueur":"5 cm"},{"id":"z2","de":"B","a":"F"},{"id":"z3","de":"F","a":"E"},{"id":"z4","de":"E","a":"A"},{"id":"z5","de":"B","a":"C","longueur":"4 cm"},{"id":"z6","de":"F","a":"G"},{"id":"z7","de":"C","a":"G"},{"id":"z8","de":"E","a":"H"},{"id":"z9","de":"H","a":"G"},{"id":"z10","de":"A","a":"D","style":"pointilles"},{"id":"z11","de":"D","a":"C","style":"pointilles"},{"id":"z12","de":"D","a":"H","style":"pointilles"}],"polygones":[{"sommets":["E","F","G","H"],"teinte":"jaune","motif":"clair"}]}],"questions":[{"enonce":"Touche **toutes** les arêtes parallèles à [AB], en plus de [AB] elle-même.","aide":"Dans un pavé droit, il y a quatre arêtes de même direction que [AB] : l’une est sur la face avant, une autre en bas à l’arrière.","type":"zone","document":"pave","multiple":true},{"enonce":"Quel est le **volume** de ce pavé, sachant que AB = 5 cm, BF = 3 cm et BC = 4 cm ?","aide":"Volume = longueur × largeur × hauteur.","type":"nombre","unite":"cm³"},{"enonce":"On prend A comme origine, avec les axes [AB), [AD) et [AE). Complète les coordonnées du sommet G.","aide":"Pour aller de A à G, on avance de AB sur le premier axe, de AD sur le deuxième et de AE sur le troisième.","type":"trous","segments":["G a pour coordonnées ( ",0," ; ",1," ; ",2," )."],"banque":["4","0","5","3"]},{"enonce":"Sur le dessin, la face BCGF a la forme d’un parallélogramme. Que peut-on dire de cette face dans le vrai pavé ?","aide":"Dans un pavé droit, toutes les faces sont des rectangles.","type":"choix","options":[{"id":"a","texte":"Un losange dont les côtés sont tous égaux"},{"id":"b","texte":"Un rectangle : la perspective déforme les angles droits"},{"id":"c","texte":"Un carré dont les quatre côtés sont égaux"},{"id":"d","texte":"Un parallélogramme qui n’est pas un rectangle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z11","z3","z9"]},"explication":"Les arêtes **[DC], [FE] et [HG]** sont parallèles à [AB] : le parallélisme est conservé en perspective cavalière."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 cm³","explication":"5 × 4 × 3 = **60 cm³**. Sur le dessin, BC paraît plus courte que 4 cm : les longueurs des fuyantes ne sont pas conservées."},{"cle":{"type":"trous","trous":[["5"],["4"],["3"]]},"affichage":"5 · 4 · 3","explication":"G est au bout des trois arêtes : **(5 ; 4 ; 3)**, puisque AB = 5, AD = BC = 4 et AE = BF = 3."},{"cle":{"type":"choix","ids":["b"]},"explication":"Toutes les faces d’un pavé droit sont des **rectangles**. En perspective cavalière, les angles droits ne sont conservés que sur la face avant : les autres faces apparaissent en parallélogrammes."}]$ex$::jsonb),
  ('f91e9054-fdd3-5d3e-8910-de90cc5862b9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une baguette dans le coffre de rangement","competence":"geometrie","situation":"Léna veut ranger une baguette de bois de 5,2 dm dans un coffre à jouets. Le coffre est un pavé droit. Elle se demande si la baguette tiendra à plat sur le fond du coffre.","documents":[{"id":"coffre","type":"solide","titre":"Le coffre","longueur":4,"largeur":3,"hauteur":2,"cotes":true,"unite":"dm"},{"id":"fond","type":"figure","titre":"Le fond du coffre, vu de dessus","source":"Dessin à l’échelle : 1 carreau = 1 dm","cadre":{"xmin":0,"xmax":6,"ymin":0,"ymax":5},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":5,"y":1,"position":"se"},{"id":"C","x":5,"y":4,"position":"ne"},{"id":"D","x":1,"y":4,"position":"no"}],"segments":[{"id":"z1","de":"A","a":"B","longueur":"4 dm"},{"id":"z2","de":"B","a":"C","longueur":"3 dm"},{"id":"z3","de":"C","a":"D"},{"id":"z4","de":"D","a":"A"},{"id":"z5","de":"A","a":"C","style":"pointilles"}],"angles":[{"sommet":"B","de":"A","a":"C","droit":true}]}],"questions":[{"enonce":"Quel est le **volume** du coffre, en dm³ ?","aide":"Longueur × largeur × hauteur.","type":"nombre","unite":"dm³"},{"enonce":"Touche le segment qui est l’**hypoténuse** du triangle ABC.","aide":"L’hypoténuse est le côté opposé à l’angle droit.","type":"zone","document":"fond","multiple":false},{"enonce":"Calcule la longueur de la diagonale [AC] du fond.","aide":"Pythagore dans ABC rectangle en B : AC² = AB² + BC².","type":"nombre","unite":"dm"},{"enonce":"La baguette de 5,2 dm peut-elle être posée à plat sur le fond du coffre ?","aide":"La plus grande longueur qu’on peut poser à plat sur un fond rectangulaire est sa diagonale.","type":"choix","options":[{"id":"a","texte":"Oui : le fond est assez grand, son aire est de 12 dm²"},{"id":"b","texte":"Oui : elle est plus courte que la longueur du coffre"},{"id":"c","texte":"Oui : 5,2 dm est inférieur à 4 + 3 = 7 dm"},{"id":"d","texte":"Non : elle dépasse la diagonale du fond, qui mesure 5 dm"}],"multiple":false},{"enonce":"Quelle est la longueur de la diagonale de la **face avant** (4 dm de long, 2 dm de haut) ? Arrondis au dixième de dm.","aide":"Même méthode, dans le rectangle de la face avant : d² = 4² + 2².","type":"nombre","unite":"dm"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 dm³","explication":"4 × 3 × 2 = **24 dm³**, soit 24 litres."},{"cle":{"type":"zone","ids":["z5"]},"explication":"L’angle droit est en B : l’hypoténuse du triangle ABC est **[AC]**, la diagonale du fond."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 dm","explication":"AC² = 4² + 3² = 16 + 9 = 25, donc AC = √25 = **5 dm**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La plus longue baguette qui tient à plat est de **5 dm** (la diagonale). Avec 5,2 dm, elle ne tient pas : l’aire du fond ne suffit pas à répondre, c’est la longueur de la diagonale qui compte."},{"cle":{"type":"nombre","valeur":4.5,"tolerance":0.05},"affichage":"4,5 dm","explication":"d² = 16 + 4 = 20, donc d = √20 ≈ **4,5 dm**."}]$ex$::jsonb),
  ('58cfa258-69f9-5109-927a-c51fd8fae8c7'::uuid, 1, 1, 5, 20, 4,
