  ('58cfa258-69f9-5109-927a-c51fd8fae8c7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le cornet de glace","competence":"geometrie","situation":"Au stand de glaces, le vendeur pose une boule dans un cornet en forme de cône de révolution. Mia aimerait savoir combien de crème glacée il peut contenir.","documents":[{"id":"cone","type":"schema","titre":"Le cornet de glace","largeur":320,"hauteur":245,"source":"Dessin de profil, pas à l’échelle","elements":[{"forme":"polygone","points":[[160,28],[80,172],[240,172]],"teinte":"ambre","motif":"clair"},{"forme":"ellipse","cx":160,"cy":172,"rx":80,"ry":16,"teinte":"sable","motif":"clair"},{"forme":"ligne","de":[160,28],"a":[80,172],"epaisseur":2,"id":"z1","zone":true},{"forme":"ligne","de":[160,28],"a":[240,172],"epaisseur":2,"id":"z2","zone":true},{"forme":"ligne","de":[160,28],"a":[160,172],"style":"pointilles","teinte":"violet"},{"forme":"ligne","de":[151,172],"a":[151,163],"epaisseur":1},{"forme":"ligne","de":[151,163],"a":[160,163],"epaisseur":1},{"forme":"ligne","de":[80,208],"a":[240,208],"fleche":"deux"},{"forme":"texte","x":160,"y":228,"texte":"diamètre de la base : 6 cm","ancre":"milieu"},{"forme":"etiquette","x":262,"y":75,"texte":"hauteur : 4 cm","vers":[164,100]}]}],"questions":[{"enonce":"Touche les **deux génératrices** visibles sur le dessin.","aide":"Une génératrice joint le sommet à un point du bord de la base.","type":"zone","document":"cone","multiple":true},{"enonce":"Quelle est la longueur d’une **génératrice**, en cm ?","aide":"Le rayon vaut la moitié du diamètre. Le triangle formé par la hauteur, le rayon et la génératrice est rectangle : Pythagore !","type":"nombre","unite":"cm"},{"enonce":"Quel est le **volume** du cornet, arrondi à l’unité ?","aide":"V = {{1/3}} × π × R² × h, avec R = 3 cm et h = 4 cm.","type":"nombre","unite":"cm³"},{"enonce":"Un cylindre de même base et de même hauteur contiendrait combien de fois plus que le cornet ?","aide":"Compare la formule du cône à celle du cylindre : π × R² × h.","type":"choix","options":[{"id":"a","texte":"3 fois plus"},{"id":"b","texte":"2 fois plus"},{"id":"c","texte":"4 fois plus"},{"id":"d","texte":"π fois plus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"Les deux côtés obliques du cône sont des **génératrices**. La hauteur, elle, est en pointillés : c’est un autre segment."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 cm","explication":"Rayon : 6 ÷ 2 = 3 cm. Génératrice² = 3² + 4² = 25, donc la génératrice mesure **5 cm**."},{"cle":{"type":"nombre","valeur":38,"tolerance":0},"affichage":"38 cm³","explication":"V = {{1/3}} × π × 3² × 4 = 12 × π ≈ 37,7, soit **38 cm³** (38 mL de glace)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le cône a pour volume le **tiers** de celui du cylindre : le cylindre en contient **3 fois plus**, soit 36 × π ≈ 113 cm³."}]$ex$::jsonb),
