  ('990b3f90-a500-56fe-8672-24b970637547'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La maquette du voilier de Maya","competence":"calculer","situation":"Maya a construit une maquette de voilier à l’échelle 1/25. Elle a mesuré les pièces de sa maquette et veut connaître les mesures du vrai bateau.","documents":[{"id":"maquette","type":"tableau","titre":"Les mesures de la maquette","source":"Mesures imaginées pour l’exercice","colonnes":["Pièce","Sur la maquette (cm)","En réalité"],"lignes":[["Longueur de la coque",40,"? m"],["Hauteur du mât",30,"? m"],["Largeur de la coque",12,"? m"]],"enteteLignes":true}],"questions":[{"enonce":"À l’échelle 1/25, par combien multiplie-t-on une longueur de la maquette pour obtenir la réalité ?","aide":"Une échelle 1/25 veut dire que 1 cm sur la maquette représente 25 cm en réalité.","type":"choix","options":[{"id":"a","texte":"Par 25"},{"id":"b","texte":"Par 0,25"},{"id":"c","texte":"Par 50"},{"id":"d","texte":"Par 625"}],"multiple":false},{"enonce":"Quelle est la **longueur réelle de la coque**, en mètres ?","aide":"Multiplie 40 cm par 25, puis convertis en mètres (100 cm = 1 m).","type":"nombre","unite":"m"},{"enonce":"Quelle est la **hauteur réelle du mât**, en mètres ?","aide":"Même méthode : × 25, puis des cm en m.","type":"nombre","unite":"m"},{"enonce":"Le gouvernail réel mesure 2 m. Complète pour trouver sa taille sur la maquette.","aide":"Passe 2 m en centimètres, puis divise par 25.","type":"trous","segments":["Sur la maquette, le gouvernail mesure ",0," cm."],"banque":["200","2","8","50"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"On multiplie les longueurs **par 25** : c’est le rapport k de l’agrandissement."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 m","explication":"40 × 25 = 1 000 cm, soit **10 m**."},{"cle":{"type":"nombre","valeur":7.5,"tolerance":0},"affichage":"7,5 m","explication":"30 × 25 = 750 cm, soit **7,5 m**."},{"cle":{"type":"trous","trous":[["8"]]},"affichage":"8","explication":"2 m = 200 cm, et 200 ÷ 25 = **8 cm** : pour passer de la réalité à la maquette, on divise par 25."}]$ex$::jsonb),
  ('990b3f90-a500-56fe-8672-24b970637547'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le plan du terrain de la mairie","competence":"geometrie","situation":"La mairie fait aménager un terrain rectangulaire. Le plan est dessiné à l’échelle 1/500 : 1 cm sur le plan représente 500 cm, soit 5 m, sur le terrain.","documents":[{"id":"plan","type":"figure","titre":"Le plan du terrain","source":"Plan à l’échelle 1/500 : un carreau mesure 1 cm sur le plan","cadre":{"xmin":0,"xmax":8,"ymin":0,"ymax":6},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":7,"y":1,"position":"se"},{"id":"C","x":7,"y":5,"position":"ne"},{"id":"D","x":1,"y":5,"position":"no"}],"segments":[{"id":"z1","de":"A","a":"B","longueur":"6 cm"},{"id":"z2","de":"B","a":"C","longueur":"4 cm"},{"id":"z3","de":"C","a":"D"},{"id":"z4","de":"D","a":"A"}],"polygones":[{"sommets":["A","B","C","D"],"teinte":"vert","motif":"clair"}],"angles":[{"sommet":"A","de":"B","a":"D","droit":true}]}],"questions":[{"enonce":"Touche le côté du terrain qui mesure **30 m** en réalité.","aide":"1 cm sur le plan vaut 5 m en réalité : convertis la longueur de chaque côté.","type":"zone","document":"plan","multiple":false},{"enonce":"Quelle est la **largeur réelle** du terrain, c’est-à-dire la longueur du côté [BC], en mètres ?","aide":"BC mesure 4 cm sur le plan.","type":"nombre","unite":"m"},{"enonce":"Quelle est l’**aire réelle** du terrain ?","aide":"Calcule les dimensions réelles, puis l’aire du rectangle.","type":"nombre","unite":"m²"},{"enonce":"Un élève multiplie l’aire du plan, 24 cm², par 500 pour trouver l’aire réelle. Quelle est son erreur ?","aide":"Quand les longueurs sont multipliées par k, par combien les aires sont-elles multipliées ?","type":"choix","options":[{"id":"a","texte":"Une aire ne peut pas se lire sur un plan"},{"id":"b","texte":"Les aires se multiplient par 500², pas par 500"},{"id":"c","texte":"Il aurait dû diviser l’aire par 500"},{"id":"d","texte":"Il a oublié de convertir les cm² en cm³"}],"multiple":false}]}$ex$::jsonb,
