e de ce nombre de jours depuis samedi.","type":"choix","options":[{"id":"a","texte":"Mardi"},{"id":"b","texte":"Lundi"},{"id":"c","texte":"Samedi"},{"id":"d","texte":"Dimanche"}],"multiple":false}]}$ex$::jsonb,
