   $ex${"titre":"Les bouquets du fleuriste","competence":"modeliser","situation":"Un fleuriste prépare des bouquets tous identiques, sans aucune fleur en trop. Il doit utiliser toutes ses roses et toutes ses tulipes, et il en fait le plus possible. Il remplit son bon de commande, puis demande l’avis de Hugo et Lou.","documents":[{"id":"bon","type":"fiche","modele":"ticket","titre":"Le bon de commande","entete":"Fleuriste Le Lilas","emoji":"💐","lignes":[{"texte":"Roses","valeur":"36","id":"z1"},{"texte":"Tulipes","valeur":"48","id":"z2"}],"pied":"Bon écrit pour l’exercice"},{"id":"dial","type":"dialogue","modele":"bulles","titre":"Hugo et Lou réfléchissent","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Lou","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Avec 9 bouquets, chacun aurait 4 roses : 36 ÷ 9 = 4. Ça marche !"},{"qui":"Lou","texte":"Et pour les tulipes ? Il faut que ça marche pour les deux."}]}],"questions":[{"enonce":"Pourquoi 9 bouquets ne conviennent-ils pas ?","aide":"Calcule 48 ÷ 9 : le résultat tombe-t-il juste ?","type":"choix","options":[{"id":"a","texte":"9 est un diviseur de 36 et de 48"},{"id":"b","texte":"9 est un diviseur de 48 mais pas de 36"},{"id":"c","texte":"9 n’est un diviseur ni de 36 ni de 48"},{"id":"d","texte":"9 est un diviseur de 36 mais pas de 48"}],"multiple":false},{"enonce":"Range chaque nombre : divise-t-il à la fois 36 et 48 ?","aide":"Teste chaque nombre sur 36 ET sur 48 : il doit tomber juste deux fois.","type":"categories","categories":[{"id":"c0","texte":"Diviseur de 36 et de 48"},{"id":"c1","texte":"Ne convient pas"}],"items":[{"id":"i0","texte":"24"},{"id":"i1","texte":"9"},{"id":"i2","texte":"8"},{"id":"i3","texte":"12"},{"id":"i4","texte":"6"},{"id":"i5","texte":"4"}]},{"enonce":"Quel est le plus grand nombre de bouquets identiques que le fleuriste peut faire ?","aide":"Cherche le plus grand diviseur commun de 36 et 48.","type":"nombre","unite":"bouquets"},{"enonce":"Compose un bouquet quand le fleuriste en fait 12.","aide":"Partage 36 roses puis 48 tulipes en 12 bouquets égaux.","type":"trous","segments":["Chaque bouquet contient ",0," roses et ",1," tulipes."],"banque":["4","3","9","12","6","2"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"36 = 9 × 4, donc 9 divise 36 ; mais 48 = 9 × 5 + 3, donc 9 **ne divise pas 48**. Le nombre de bouquets doit diviser les deux."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c0"}},"explication":"6, 12 et 4 divisent 36 et 48. 8 et 24 divisent 48 mais pas 36 ; 9 divise 36 mais pas 48."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 bouquets","explication":"Les diviseurs communs de 36 et 48 sont 1, 2, 3, 4, 6 et **12** : le fleuriste fait au plus 12 bouquets."},{"cle":{"type":"trous","trous":[["3"],["4"]]},"affichage":"3 · 4","explication":"36 ÷ 12 = **3 roses** et 48 ÷ 12 = **4 tulipes** : aucun reste, tout est utilisé."}]$ex$::jsonb),
  ('c0bf100f-b4c4-5cdb-92dd-f004e501c944'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les dossards du cross","competence":"raisonner","situation":"Le jour du cross, les cinq premiers coureurs portent des dossards numérotés. Le professeur prépare des paniers : les dossards divisibles par 5 auront une bouteille, ceux divisibles par 3 un fruit. Il ne veut poser aucune division.","documents":[{"id":"dossards","type":"tableau","titre":"Les cinq premiers dossards","colonnes":["Coureur A","Coureur B","Coureur C","Coureur D","Coureur E"],"lignes":[["340","1 252","2 715","6 003","4 580"]],"enteteLignes":false,"source":"Numéros inventés pour l’exercice"}],"questions":[{"enonce":"Touche tous les dossards divisibles par 5.","aide":"Regarde le dernier chiffre de chaque numéro.","type":"zone","document":"dossards","multiple":true},{"enonce":"Touche tous les dossards divisibles par 3.","aide":"Additionne les chiffres de chaque numéro : la somme doit être divisible par 3.","type":"zone","document":"dossards","multiple":true},{"enonce":"Le dossard 6 003 est-il divisible par 9 ?","aide":"Pour 9, regarde la somme des chiffres, comme pour 3.","type":"choix","options":[{"id":"a","texte":"Non : il se termine par un 3"},{"id":"b","texte":"Non : la somme de ses chiffres vaut 6"},{"id":"c","texte":"Oui : la somme de ses chiffres vaut 9"},{"id":"d","texte":"Oui : il se termine par 03"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r0c2","r0c4"]},"explication":"Un nombre est divisible par 5 s’il se termine par 0 ou 5 : **340, 2 715 et 4 580**."},{"cle":{"type":"zone","ids":["r0c2","r0c3"]},"explication":"2 + 7 + 1 + 5 = 15 et 6 + 0 + 0 + 3 = 9 sont divisibles par 3 : **2 715 et 6 003**. Pour 340 (somme 7), 1 252 (10) et 4 580 (17), ce n’est pas le cas."},{"cle":{"type":"choix","ids":["c"]},"explication":"6 + 0 + 0 + 3 = 9, et 9 est divisible par 9 : **6 003 est divisible par 9** (6 003 = 9 × 667)."}]$ex$::jsonb),
  ('c0bf100f-b4c4-5cdb-92dd-f004e501c944'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le numéro de lot effacé","competence":"resoudre","situation":"Dans un entrepôt, un numéro de lot est à moitié effacé : il s’écrit 4■72, où ■ est un chiffre. Le chef sait que le lot est divisible par 9 ; il cherche le chiffre manquant. Plus tard, Hugo vérifie un critère sur un autre numéro de lot.","documents":[{"id":"lot","type":"fiche","modele":"ticket","titre":"L’étiquette du lot","entete":"Entrepôt du Nord","sousTitre":"Lot à identifier","emoji":"📦","lignes":[{"texte":"Numéro du lot","valeur":"4■72","id":"z1","gras":true},{"texte":"Divisible par","valeur":"9"}],"pied":"Étiquette écrite pour l’exercice"},{"id":"dial","type":"dialogue","modele":"bulles","titre":"Hugo et Lina vérifient un autre lot","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Lina","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"1 236 est divisible par 2 et par 4, donc par 8 !"},{"qui":"Lina","texte":"Pas si vite : fais la division pour voir."}]}],"questions":[{"enonce":"Quelle est la somme des chiffres connus du lot 4■72 ?","aide":"Additionne 4, 7 et 2 sans compter le chiffre effacé.","type":"nombre"},{"enonce":"Quel chiffre ■ faut-il écrire pour que 4■72 soit divisible par 9 ?","aide":"La somme des chiffres doit être un multiple de 9. Quel multiple de 9 suit 13 ?","type":"nombre"},{"enonce":"Le lot 4 572 est-il divisible par 4 ?","aide":"Pour 4, regarde le nombre formé par les deux derniers chiffres.","type":"choix","options":[{"id":"a","texte":"Oui : 72 est divisible par 4"},{"id":"b","texte":"Non : il ne se termine pas par 0 ou 5"},{"id":"c","texte":"Oui : il se termine par un chiffre pair"},{"id":"d","texte":"Non : la somme de ses chiffres n’est pas divisible par 4"}],"multiple":false},{"enonce":"Complète la conclusion sur 4 572.","aide":"Il est divisible par 9, donc aussi par un diviseur de 9. Combine ensuite 2 avec ce diviseur.","type":"trous","segments":["4 572 est divisible par 2 et par ",0," , donc par ",1," ."],"banque":["5","9","4","3","8","6"]},{"enonce":"Hugo a-t-il raison de dire que 1 236, divisible par 2 et par 4, l’est par 8 ?","aide":"Pose la division de 1 236 par 8.","type":"choix","options":[{"id":"a","texte":"Non : 1 236 n’est même pas un nombre divisible par 4"},{"id":"b","texte":"Non : 2 et 4 ne sont pas premiers entre eux (reste 4)"},{"id":"c","texte":"Oui : un nombre divisible par 2 et par 4 l’est toujours par 8"},{"id":"d","texte":"Oui : 1 236 ÷ 8 donne bien un nombre entier, sans reste"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13","explication":"4 + 7 + 2 = **13**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"13 + ■ doit valoir 18 (le multiple de 9 qui suit 13) : ■ = **5**. Le lot est 4 572."},{"cle":{"type":"choix","ids":["a"]},"explication":"72 = 4 × 18 : les deux derniers chiffres forment un multiple de 4, donc **4 572 est divisible par 4**."},{"cle":{"type":"trous","trous":[["3"],["6"]]},"affichage":"3 · 6","explication":"4 572 est divisible par 9, donc par **3**. Étant divisible par 2 et par 3 (premiers entre eux), il l’est par **6**."},{"cle":{"type":"choix","ids":["b"]},"explication":"1 236 = 8 × 154 + 4 : **il n’est pas divisible par 8**. Combiner deux critères ne marche que si les deux diviseurs sont premiers entre eux."}]$ex$::jsonb),
