  ('0d56d33e-0375-5914-8834-470c354ed4f9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le prix de la place de cinéma","competence":"modeliser","situation":"Le cinéma de Valentine a modifié le prix de sa place deux années de suite. Elle veut mesurer ces évolutions et comprendre pourquoi on ne revient pas au prix de départ.","documents":[{"id":"prix","type":"tableau","titre":"Le prix de la place de cinéma","colonnes":["Année","2022","2023","2024"],"lignes":[["Prix (€)","8,00","9,60","8,64"]],"enteteLignes":true,"source":"Prix inventés pour l’exercice"}],"questions":[{"enonce":"De quel pourcentage le prix a-t-il augmenté de 2022 à 2023 ?","aide":"Calcule (valeur finale − valeur initiale) ÷ valeur initiale × 100.","type":"nombre","unite":"%"},{"enonce":"De quel pourcentage le prix a-t-il baissé de 2023 à 2024 ?","aide":"Cette fois, la valeur initiale est le prix de 2023.","type":"nombre","unite":"%"},{"enonce":"Quelle est l’évolution globale du prix entre 2022 et 2024 ?","aide":"Ne fais pas +20 − 10 : compare directement 8,00 € et 8,64 €. Ou multiplie les coefficients 1,2 et 0,9.","type":"choix","options":[{"id":"a","texte":"Une hausse de 10 %"},{"id":"b","texte":"Une hausse de 8 %"},{"id":"c","texte":"Aucune évolution"},{"id":"d","texte":"Une baisse de 10 %"}],"multiple":false},{"enonce":"Avec sa carte, Valentine paie 7,20 € après une réduction de 20 %. Quel était le prix affiché de la place ?","aide":"Le prix payé vaut 0,8 fois le prix affiché : il faut diviser, pas ajouter 20 %.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"(9,60 − 8,00) ÷ 8,00 × 100 = 1,60 ÷ 8 × 100 = **+20 %**."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 %","explication":"(8,64 − 9,60) ÷ 9,60 × 100 = −0,96 ÷ 9,60 × 100 = **−10 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les coefficients se **multiplient** : 1,2 × 0,9 = 1,08, soit **+8 %**. Une hausse de 20 % puis une baisse de 10 % ne s’annulent pas."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 €","explication":"7,20 ÷ 0,8 = **9 €**. Ajouter 20 % à 7,20 € donnerait 8,64 €, ce qui serait faux : la remise porte sur le prix affiché."}]$ex$::jsonb),
