  ('787349c7-b624-5bb9-a75e-0e76edf04e0f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les baguettes du cerf-volant","competence":"raisonner","situation":"Léa construit des cerfs-volants avec trois baguettes. Avant de couper, elle teste plusieurs triplets de longueurs : tous ne permettent pas de fermer un triangle.","documents":[{"id":"essais","type":"tableau","titre":"Les essais de Léa","colonnes":["Essai","Côté 1","Côté 2","Côté 3"],"lignes":[["Essai A","5 cm","6 cm","10 cm"],["Essai B","3 cm","4 cm","7 cm"],["Essai C","2 cm","3 cm","6 cm"],["Essai D","4 cm","5 cm","8 cm"]],"enteteLignes":false,"source":"Longueurs inventées pour l’exercice"}],"questions":[{"enonce":"Touche l’essai impossible : on ne peut pas en faire un triangle.","aide":"Additionne les deux plus petits côtés : le résultat doit dépasser le plus grand.","type":"zone","document":"essais","multiple":false},{"enonce":"Range chaque essai selon ce qu’il donne.","aide":"Compare la somme des deux petits côtés au plus grand côté : plus grande, égale ou plus petite ?","type":"categories","categories":[{"id":"c0","texte":"Triangle constructible"},{"id":"c1","texte":"Points alignés"},{"id":"c2","texte":"Impossible"}],"items":[{"id":"i0","texte":"Essai A"},{"id":"i1","texte":"Essai D"},{"id":"i2","texte":"Essai C"},{"id":"i3","texte":"Essai B"}]},{"enonce":"Léa a déjà coupé deux baguettes de 5 cm et de 8 cm. Quelle est la plus grande longueur entière possible pour la troisième ?","aide":"La troisième baguette doit être strictement plus courte que la somme des deux autres.","type":"nombre","unite":"cm"},{"enonce":"Avec ces mêmes baguettes de 5 cm et de 8 cm, quelle est la plus petite longueur entière possible pour la troisième ?","aide":"Le plus grand côté (8 cm) doit rester plus petit que la somme des deux autres : 8 < 5 + x.","type":"nombre","unite":"cm"}]}$ex$::jsonb,
