on change un seul aspect : rythme, harmonie, mode ou instrumentation.","type":"association","gauche":[{"id":"g0","texte":"Variation 1"},{"id":"g1","texte":"Variation 2"},{"id":"g2","texte":"Variation 3"}],"droite":[{"id":"d0","texte":"L’instrumentation"},{"id":"d1","texte":"Le mode"},{"id":"d2","texte":"Le rythme"}]},{"enonce":"Quel passage du tableau n’est **pas** une vraie variation ?","aide":"Dans un thème et variations, le thème reste reconnaissable sous ses déguisements.","type":"choix","options":[{"id":"a","texte":"Variation 3"},{"id":"b","texte":"Variation 1"},{"id":"c","texte":"Variation 2"},{"id":"d","texte":"Variation 4"}],"multiple":false},{"enonce":"Touche **la réponse**, c’est-à-dire l’entrée de la deuxième voix qui reprend le sujet.","aide":"Cherche la lettre R dans la légende, puis dans le schéma.","type":"zone","document":"fugue","multiple":false},{"enonce":"Complète la structure d’une fugue.","aide":"Regarde la légende du schéma : trois éléments y sont nommés.","type":"trous","segments":["Dans une fugue, on entend un ",0,", une ",1," et des ",2," qui s’enchaînent."],"banque":["refrain","sujet","épisodes","couplets","réponse"]}]}$ex$::jsonb,
